import math

def otherside_rightangle(w, h):
    """Return the third side of a right-angled triangle given the other two sides.

    Use Pythagoras' theorem: c = sqrt(a^2 + b^2) for the hypotenuse
    or use c = sqrt(a^2 - b^2) or b = sqrt(c^2 - a^2) depending on w and h.
    """
    if w == 0 or h == 0:
        return 0.0  # degenerate triangle case

    # Ensure w and h are not the hypotenuse (since hypotenuse must be the longest side)
    if w > h:
        return math.sqrt(w**2 - h**2)
    else:
        return math.sqrt(h**2 - w**2)
