def count_binary_seq(n):
    if n == 0:
        return 1.0
    # Initialize a DP table where dp[i][j][k] represents the number of sequences
    # of length 2*i with sum of first i bits equal to j and sum of last i bits equal to k
    dp = [[[0] * (n + 1) for _ in range(n + 1)] for __ in range(n + 1)]
    dp[0][0][0] = 1

    for i in range(1, n + 1):
        for j in range(n + 1):
            for k in range(n + 1):
                if dp[i-1][j][k] > 0:
                    # Try appending bit 0 to first half and bit 0 to last half
                    dp[i][j][k] += dp[i-1][j][k]
                    # Try appending bit 1 to first half and bit 0 to last half
                    if j < n:
                        dp[i][j+1][k] += dp[i-1][j][k]
                    # Try appending bit 0 to first half and bit 1 to last half
                    if k < n:
                        dp[i][j][k+1] += dp[i-1][j][k]
                    # Try appending bit 1 to first half and bit 1 to last half
                    if j < n and k < n:
                        dp[i][j+1][k+1] += dp[i-1][j][k]

    # Return the sum of all valid sequences where first n bits sum equals last n bits sum
    return sum(dp[n][j][j] for j in range(n + 1))
